python3 -I - <<'E'
import sqlite3
c=sqlite3.connect('file:claims.sqlite?mode=ro',uri=True)
c.row_factory=sqlite3.Row
auth={r['staff_id']:r['settlement_authority_gbp'] for r in c.execute('select * from staff')}
cl={r['claim_id']:dict(r) for r in c.execute('select * from claims')}
pay={}
for r in c.execute('select * from claim_payments'):pay.setdefault(r['claim_id'],[]).append(dict(r))
it={}
for r in c.execute('select * from claim_items'):it.setdefault(r['claim_id'],[]).append(dict(r))
for k,v in cl.items():
    s=v['proposed_settlement_gbp']
    if s and v['approved_by'] and auth[v['approved_by']]<s: print('AUTH',k,s,v['approved_by'])
    ps=pay.get(k,[])
    ex=sum(p['excess_deducted_gbp'] for p in ps if p['direction']=='Paid' and p['payment_type']!='Complaint redress')
    net=sum(p['net_amount_gbp'] for p in ps if p['direction']=='Paid' and p['payment_type']!='Complaint redress')
    if ex>v['excess_gbp']+.001: print('EXCESS>',k,ex,v['excess_gbp'])
    if ps and v['claim_status'].startswith('Settled') and abs(net-(s or 0))>.01: print('NETDIFF',k,net,s)
    ag=sum(i['agreed_amount_gbp'] or 0 for i in it.get(k,[]))
    if s and abs(ag-v['excess_gbp']-s)>.01 and ag: print('ITEMDIFF',k,ag,v['excess_gbp'],s)
    if s and abs(v['claimed_amount_gbp']-v['excess_gbp']-s)>.01: print('CLAIMDIFF',k,v['claimed_amount_gbp'],v['excess_gbp'],s)
    if v['claim_status']=='Settled' and not ps: print('NOPAY',k)
# duplicates
seen={}
for k,l in it.items():
    for i in l:
        if i['supplier_id'] and i['claimed_amount_gbp']>300: seen.setdefault((i['supplier_id'],i['claimed_amount_gbp']),[]).append((k,i['document_ref']))
for key,v in seen.items():
    if len(v)>1:print('DUP',key,v)
E
